"use strict";
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const uid=()=>Math.random().toString(36).slice(2,9)+Date.now().toString(36).slice(-4);
const esc=s=>String(s??"").replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const nowISO=()=>new Date().toISOString();
const LS_KEY="novelstudio_v1";
let S=null; // store
let UI={view:"home", novelId:null, chapterId:null, sceneId:null, aiTab:"Chat", chatId:null, boardView:"Board", planChapter:null, preview:null, lastSelection:"", editMode:"Standard", width:"Standard"};
function toast(m){const d=document.createElement("div");d.className="toast";d.innerHTML=m;$("#toasts").appendChild(d);setTimeout(()=>d.remove(),3800);}
function words(t){t=String(t||"").replace(/<[^>]*>/g," ").trim();return t? t.split(/\s+/).length:0;}
function chars(t){return String(t||"").replace(/<[^>]*>/g,"").length;}
function readTime(t){return Math.max(1,Math.round(words(t)/200));}
/* ---------- STORE ---------- */
function defaultProfiles(){return [{id:"local",name:"On-device (offline)",provider:"local",baseUrl:"",path:"",model:"local-storyteller",temp:.8},{id:"pollinations",name:"Pollinations Cloud (free key)",provider:"openai",baseUrl:"https://text.pollinations.ai",path:"/openai",model:"openai",apiKey:"",temp:.8},{id:"openai",name:"OpenAI-compatible key",provider:"openai",baseUrl:"https://api.openai.com",path:"/chat/completions",model:"gpt-4o-mini",apiKey:"",temp:.8}];}
function ensureProfiles(){if(!Array.isArray(S.profiles)||!S.profiles.length)S.profiles=defaultProfiles();let changed=false;const have=new Set(S.profiles.map(p=>p.id));defaultProfiles().forEach(d=>{if(!have.has(d.id)){S.profiles.push({...d});changed=true;}});S.profiles.forEach(p=>{if(p.path===undefined){p.path=p.provider==="local"?"":(p.baseUrl||"").includes("pollinations")?"/openai":"/chat/completions";changed=true;}});if(!S.profiles.find(p=>p.id===S.activeProfile))S.activeProfile="local";return changed;}
function blankStore(){return {novels:[],chats:[],profiles:defaultProfiles(),activeProfile:"local",settings:{theme:"midnight-library",bg:"grand-library",bgBlur:2,bgDim:.55,bgOpacity:.28,showSplash:true,accent:"#c9a35c",editorFont:"Georgia, serif",editorSize:18,lineHeight:1.8,goal:500,autoBackup:true,typewriter:false,sounds:false},trash:[],writingLog:[],prompts:[],series:[]};}
function save(){try{S.ui={novelId:UI.novelId,chapterId:UI.chapterId,view:UI.view,chatId:UI.chatId};localStorage.setItem(LS_KEY,JSON.stringify(S));setSave(navigator.onLine===false?"Offline":"Saved");mirrorStore();}catch(e){setSave("Error");}}
function load(){try{const r=localStorage.getItem(LS_KEY);S=r?JSON.parse(r):blankStore();}catch{S=blankStore();} if(!S||typeof S!=="object")S=blankStore();if(!S.settings)S.settings=blankStore().settings;if(!Array.isArray(S.novels))S.novels=[];if(ensureProfiles()){try{localStorage.setItem(LS_KEY,JSON.stringify(S));}catch{}}if(S.ui){UI.novelId=S.ui.novelId;UI.chapterId=S.ui.chapterId;UI.view=S.ui.view||"home";UI.chatId=S.ui.chatId;}}
function setSave(t){const e=$("#saveState");if(e){e.textContent=(t==="Saved"?"● Saved":t==="Saving"?"◌ Saving…":t==="Offline"?"○ Offline":"● "+t);e.style.color=t==="Saved"?"var(--ok)":t==="Saving"?"var(--warn)":"var(--bad)";}const f=$("#focusSave");if(f)f.textContent=t;}
/* ---------- IndexedDB persistence (images, covers, full-store mirror) ---------- */
const IDB_DB="novelstudio", IDB_STORE="blobs";
let _idb=null, _idbMem=new Map(), _mirrorT=null;
function idb(){return new Promise((res,rej)=>{if(_idb)return res(_idb);try{const q=indexedDB.open(IDB_DB,1);q.onupgradeneeded=()=>{q.result.createObjectStore(IDB_STORE);};q.onsuccess=()=>{_idb=q.result;res(_idb);};q.onerror=()=>rej(q.error);}catch(e){rej(e);}});}
async function idbPut(key,val){_idbMem.set(key,val);try{const db=await idb();await new Promise((res,rej)=>{const tx=db.transaction(IDB_STORE,"readwrite");tx.objectStore(IDB_STORE).put(val,key);tx.oncomplete=res;tx.onerror=()=>rej(tx.error);});}catch{}}
async function idbGet(key){if(_idbMem.has(key))return _idbMem.get(key);try{const db=await idb();const v=await new Promise((res,rej)=>{const tx=db.transaction(IDB_STORE,"readonly");const rq=tx.objectStore(IDB_STORE).get(key);rq.onsuccess=()=>res(rq.result);rq.onerror=()=>rej(rq.error);});if(v!==undefined)_idbMem.set(key,v);return v;}catch{return undefined;}}
async function idbAllKeys(){try{const db=await idb();return await new Promise((res,rej)=>{const tx=db.transaction(IDB_STORE,"readonly");const rq=tx.objectStore(IDB_STORE).getAllKeys();rq.onsuccess=()=>res(rq.result||[]);rq.onerror=()=>rej(rq.error);});}catch{return [];}}
function mirrorStore(){clearTimeout(_mirrorT);_mirrorT=setTimeout(async()=>{try{await idbPut("store-backup",JSON.stringify(S));const keys=await idbAllKeys();}catch{}},1200);}
async function hydrateFromIDB(){try{const bak=await idbGet("store-backup");if(bak&&(!localStorage.getItem(LS_KEY))){try{localStorage.setItem(LS_KEY,bak);load();render();toast("Restored library from on-device backup.");}catch{}}}catch{}}
/* image helpers: downscale uploads so covers/chat thumbs stay fast + persistable */
function fileToDataURL(file,maxDim=800,quality=.82){return new Promise((res,rej)=>{const rd=new FileReader();rd.onload=()=>{const img=new Image();img.onload=()=>{let{w,h}= {w:img.naturalWidth,h:img.naturalHeight};const sc=Math.min(1,maxDim/Math.max(w,h));w=Math.max(1,Math.round(w*sc));h=Math.max(1,Math.round(h*sc));const cv=document.createElement("canvas");cv.width=w;cv.height=h;cv.getContext("2d").drawImage(img,0,0,w,h);res(cv.toDataURL("image/jpeg",quality));};img.onerror=rej;img.src=rd.result;};rd.onerror=rej;rd.readAsDataURL(file);});}
function dataURLSize(dataURL){const img=new Image();return new Promise(res=>{img.onload=()=>res({w:img.naturalWidth,h:img.naturalHeight});img.onerror=()=>res({w:0,h:0});img.src=dataURL;});}
async function imagePalette(dataURL,n=4){try{const img=await new Promise((res,rej)=>{const i=new Image();i.onload=()=>res(i);i.onerror=rej;i.src=dataURL;});const cv=document.createElement("canvas");cv.width=24;cv.height=24;const cx=cv.getContext("2d",{willReadFrequently:true});cx.drawImage(img,0,0,24,24);const d=cx.getImageData(0,0,24,24).data;const buckets={};for(let i=0;i<d.length;i+=16){const k=`${d[i]>>5},${d[i+1]>>5},${d[i+2]>>5}`;buckets[k]=(buckets[k]||0)+1;}return Object.entries(buckets).sort((a,b)=>b[1]-a[1]).slice(0,n).map(([k])=>{const[r,g,b]=k.split(",").map(x=>x*32+16);return `rgb(${r},${g},${b})`;});}catch{return[];}}
function proceduralCover(title,genre){const cv=document.createElement("canvas");cv.width=512;cv.height=768;const cx=cv.getContext("2d");const pals={"Fantasy":["#2a1a4a","#c9a35c"],"Romance":["#3a1a28","#e8a0a0"],"Horror":["#0a0a0a","#8a2a2a"],"Sci-Fi":["#0a1a3a","#5aa9d6"],"Mystery":["#1a2420","#7fb069"]};const[bg,fg]=pals[genre]||["#241a10","#c9a35c"];const g=cx.createLinearGradient(0,0,0,768);g.addColorStop(0,bg);g.addColorStop(1,"#0f0b07");cx.fillStyle=g;cx.fillRect(0,0,512,768);cx.strokeStyle=fg;cx.lineWidth=6;cx.strokeRect(28,28,456,712);cx.fillStyle=fg;cx.font="28px Georgia";cx.textAlign="center";cx.fillText("❦",256,120);cx.fillStyle="#f0e6d6";cx.font="bold 44px Georgia";const words2=String(title||"Untitled").split(" ");let lines=[""],li=0;words2.forEach(w=>{if((lines[li]+" "+w).length>14){li++;lines[li]="";}lines[li]=(lines[li]+" "+w).trim();});lines.slice(0,4).forEach((l,i)=>cx.fillText(l.toUpperCase().slice(0,16),256,300+i*56));cx.font="italic 24px Georgia";cx.fillStyle=fg;cx.fillText(String(genre||"A Novel").slice(0,30),256,640);return cv.toDataURL("image/jpeg",.85);}
function novel(){return S.novels.find(n=>n.id===UI.novelId)||null;}
function cur(){const n=novel();if(!n)return null;return n;}
function allNodes(n){const out=[];(n.structure||[]).forEach(p=>{out.push(p);(p.children||[]).forEach(c=>{out.push(c);(c.children||[]).forEach(s=>{out.push(s);(s.children||[]).forEach(b=>out.push(b));});});});return out;}
function chapters(n){return allNodes(n).filter(x=>x.type==="chapter");}
function findNode(n,id){return allNodes(n).find(x=>x.id===id);}
function curChapter(){const n=novel();if(!n)return null;let c=n.structure&&UI.chapterId?findNode(n,UI.chapterId):null;if(!c){c=chapters(n)[0]||null;if(c)UI.chapterId=c.id;}return c;}
function novelWords(n){return allNodes(n).reduce((a,x)=>a+words(x.content||""),0);}
function todayWords(){const t=new Date().toDateString();return S.writingLog.filter(l=>new Date(l.date).toDateString()===t).reduce((a,l)=>a+(l.added||0),0);}
