/* ---------- AI ENGINE ---------- */
let abortAI=false;
function profile(){return S.profiles.find(p=>p.id===S.activeProfile)||S.profiles[0];}
function normBase(u){u=(u||"").trim().replace(/\/+$/,"");if(!u)return "";if(!/^https?:\/\//i.test(u))u="https://"+u;u=u.replace(/\/v1\/v1$/,"/v1").replace(/\/chat\/completions$/,"");if(!/\/v1$/.test(u))u+="/v1";return u;}
function endpointFor(p){const path=p.path||"/chat/completions";let b=(p.baseUrl||"").trim().replace(/\/+$/,"");if(!/^https?:\/\//i.test(b))b="https://"+b;if(path==="/openai"){b=b.replace(/\/v1$/,"").replace(/\/openai$/,"");return b+"/openai";}return normBase(b)+"/chat/completions";}
function modelsUrlFor(p){const path=p.path||"/chat/completions";let b=(p.baseUrl||"").trim().replace(/\/+$/,"");if(!/^https?:\/\//i.test(b))b="https://"+b;if(path==="/openai"){b=b.replace(/\/v1$/,"").replace(/\/openai$/,"");return b+"/models";}return normBase(b)+"/models";}
async function aiComplete(messages,opts={}){const p=profile();const images=opts.images||[];
if(!p||p.provider==="local") return images.length?localVision(images,messages,opts):localDraft(messages,opts);
if(!p.baseUrl)return localVision(images,messages,opts).catch(()=>localDraft(messages,opts));
/* online path: multimodal content parts when images attached */
const visionMsgs=messages.map(m=>{
  if(m.role!=="user"||!images.length)return m;
  const parts=[{type:"text",text:String(m.content||"")}];
  images.slice(0,4).forEach(u=>parts.push({type:"image_url",image_url:{url:u}}));
  return {role:m.role,content:parts};
});
const url=endpointFor(p);const body={model:p.model||opts.model||"gpt-4o-mini",messages:visionMsgs,temperature:opts.temp??p.temp??.8,stream:false};if(opts.maxTokens)body.max_tokens=opts.maxTokens;
aiStatus(images.length?"Reading images…":"Writing…");const t0=Date.now();
try{const ctrl=new AbortController();const to=setTimeout(()=>ctrl.abort(),(opts.timeout||75)*1000);$("#aiCancel").onclick=()=>{abortAI=true;ctrl.abort();};
const headers={"Content-Type":"application/json"};if(p.apiKey)headers["Authorization"]="Bearer "+p.apiKey;
const r=await fetch(url,{method:"POST",headers,body:JSON.stringify(body),signal:ctrl.signal});clearTimeout(to);
if(!r.ok){const t=await r.text().catch(()=>{});
  if(r.status===400&&images.length){ /* model without vision: retry text-only with local image notes */
    const note=await localVisionNote(images);
    const t2=await aiComplete(messages.map(m=>m.role==="user"?{...m,content:String(m.content||"")+"\n[Attached image notes: "+note+"]"}:m),{...opts,images:[]});
    return t2;
  }
  throw new Error("AI "+r.status+": "+(!p.apiKey?"no API key set — open Connect AI (🔑) to add one. ":"")+errHint(r.status)+" "+String(t).slice(0,220));}
const j=await r.json();let text=j.choices?.[0]?.message?.content||"";if(!text&&/budget/i.test(JSON.stringify(j)))throw new Error("Cloud free budget exhausted — wait ~15s and retry, add a free key in Connect AI (🔑), or switch to On-device.");
aiStatusHide();return {text,meta:{provider:p.name,model:body.model,ms:Date.now()-t0}};}
catch(e){aiStatusHide();if(abortAI){abortAI=false;throw new Error("Cancelled.");}
  if(images.length&&/Failed to fetch|NetworkError|CORS/i.test(e.message||String(e))){const v=await localVision(images,messages,opts);return v;}
  if(/Failed to fetch|NetworkError|CORS/i.test(e.message||e))throw new Error("Cannot reach "+(p.baseUrl||"endpoint")+" — offline? On-device still works: switch profile to On-device.");throw e;}}
async function localVisionNote(images){const notes=[];for(const u of images.slice(0,4)){const s=await dataURLSize(u);const pal=await imagePalette(u,3);notes.push(`${s.w}x${s.h}px, tones ${pal.join(" / ")||"muted"}`);}return notes.join("; ")||"image attached";}
async function localVision(images,messages,opts={}){ /* offline vision: real pixel read + story hooks, no key, no net */
const last=(messages[messages.length-1]&&messages[messages.length-1].content)||"Describe this image for my story.";
const note=await localVisionNote(images);
return new Promise(res=>{aiStatus("Reading images (on-device)…");setTimeout(()=>{aiStatusHide();
const n=novel();const A=(n?.characters||[])[0]?.name||"your protagonist";
res({text:`**Vision notes (on-device, offline)** — ${images.length} image${images.length>1?"s":""}: ${note}.\n\nRequest: ${String(last).slice(0,300)}\n\n- **What I can see:** dimensions + dominant tones above, read straight from the pixels (no cloud).\n- **Character read:** if this is character art, give ${A} one contrasting trait from the image (posture, palette, gaze) — don't copy the art into prose, translate it.\n- **World read:** if this is a map/place, name 3 landmarks in your own words and turn one into a lore rule with a cost.\n- **Next:** connect to cloud AI (🔑) for deeper vision prose, or reply with what the image *should* change and I'll draft the scene.`,meta:{provider:"On-device vision (offline)",model:"local-vision",ms:400}});},450);});}
function errHint(s){return {401:"invalid API key",403:"forbidden — check key/permissions",404:"model or endpoint not found",408:"timeout",429:"rate limited — wait and retry",500:"provider error",502:"bad gateway",503:"provider unavailable"}[s]||"request failed";}
function aiStatus(t){const e=$("#aiStatus");e.classList.remove("hidden");$("#aiStatusText").textContent=t||"Thinking…";}
function aiStatusHide(){$("#aiStatus").classList.add("hidden");}
/* Local offline storyteller: real template engine so every button works without a key */
const AIISMS=["It wasn't X. It was Y.","Something shifted.","heart hammered","eyes darkened","released a breath","air was thick","couldn't help but","little did","in that moment","her heart skipped","darkness crept","a shiver ran"];
function localDraft(messages,opts={}){const last=messages[messages.length-1]?.content||"";const mode=opts.mode||detectMode(last);
return new Promise(res=>{aiStatus("Writing (on-device)…");setTimeout(()=>{aiStatusHide();res({text:renderLocal(mode,last,opts),meta:{provider:"On-device (offline)",model:"local-storyteller",ms:300}});},450);});}
function detectMode(t){t=t.toLowerCase();if(t.includes("brainstorm"))return "brainstorm";if(t.includes("critic")||t.includes("analy"))return "critique";if(t.includes("dialogue"))return "dialogue";if(t.includes("rewrite"))return "rewrite";if(t.includes("polish")||t.includes("edit")||t.includes("grammar"))return "polish";if(t.includes("outline")||t.includes("plan"))return "outline";if(t.includes("twist")||t.includes("mystery"))return "mystery";if(t.includes("romance"))return "romance";if(t.includes("world"))return "world";return "continue";}
function ctxNovel(){const n=novel();if(!n)return "";const c=curChapter();return `Novel: ${n.title}. Genre: ${n.genre}. POV: ${n.bible?.pov||""}. Canon: ${(n.bible?.canon||"").slice(0,200)}. Characters: ${(n.characters||[]).map(x=>x.name).join(", ")}. Current chapter: ${c?c.title:""}. Style: ${n.style?.prose||""}, ${n.style?.pacing||""}.`;}
function renderLocal(mode,prompt,opts){const n=novel();const c=curChapter();const who=(n?.characters||[]).map(x=>x.name);const A=who[0]||"She",B=who[1]||"the stranger";
const base=`${ctxNovel()}\nRequest: ${prompt.slice(0,400)}`;
if(mode==="brainstorm")return `**Three directions (discuss before drafting):**\n\n1. **The Interruption** — A sound ${A.toLowerCase()} knows (the blue lantern sputtering) cuts the almost-confession. ${B} goes still in a way no guest would. Cost: raises dread, keeps truth hidden.\n2. **The Wrong Truth** — ${A} assumes the safest explanation and ${B} lets her, guiltily. Cost: slower burn, stronger payoff later.\n3. **The Debt Knocks** — Something small is asked in return (a name, a night of light). Cost: mystery deepens.\n\n**Critical check:** Option 1 risks convenience — earn it by planting the sputter two scenes earlier. Which thread should this serve: ${(n?.threads||[]).map(t=>t.name).join(" / ")||"main plot"}?`;
if(mode==="critique")return `**Critical story analysis (suggestions only — you decide):**\n\n- **Stakes:** the almost-confession arrives before we fear losing it. Add one quiet cost first.\n- **Setup/payoff:** if something interrupts, plant its sound one scene earlier.\n- **Character knowledge:** ${A} must not learn what only the reader knows. Check dialogue for leaks.\n- **Pacing:** allow one beat of ordinary life (tea, lighthouse chores) so tension breathes.\n- **Continuity:** verify ${(n?.bible?.canon||"locked canon")} still holds — flag conflicts, don't auto-fix.`;
if(mode==="outline")return `**Chapter plan — ${c?c.title:"current chapter"}:**\n\nGoal: deepen bond without confession.\nOpening: fog, small domestic task.\nMain events: visit → almost-truth → strange interruption → withheld answer.\nConflict: want to ask vs. fear of answer.\nEmotional beat: hope curdling into vigilance.\nReveal: none — only a clue (sound, cold, blue flicker).\nEnding hook: a question ${A} cannot un-ask.\nMust NOT happen yet: ${((n?.locks||[])[0]||{}).text||"the full reveal"}.\nTarget: ~1,200 words.`;
if(mode==="dialogue")return `**Dialogue pass:**\n\nGive ${A} short, deflecting lines ("You always knock like that?"). Give ${B} longer, careful lines that stop one word early. Add one interruption, one pause where someone doesn't answer. Keep "said" mostly; use beats (pours tea, checks lantern) instead of tags. Avoid both sounding equally poetic — ${A} is blunter when afraid.`;
if(mode==="rewrite")return rewriteLocal(opts.target||prompt);
if(mode==="polish")return polishLocal(opts.target||prompt);
if(mode==="mystery")return `**Mystery design:** plant 2 clues, 1 red herring. Clue 1: sensory (cold, sound). Clue 2: object (a key, a tide-table marked twice). Withhold the link until the midpoint. Promise: the reader can guess, but ${A} cannot yet.`;
if(mode==="romance")return `**Slow-burn beat:** raise tension without confession — prolonged task together, accidental touch withdrawn, one honest sentence immediately deflected into humor. End on care shown through action, not declaration.`;
if(mode==="world")return `**Worldbuilding:** one rule, one cost, one texture. Rule: ${(n?.world||[])[0]?.detail||"protection must be invited"}. Cost: every blue burning shortens something. Texture: salt, kerosene, wet wool. Don't exposition-dump — let the archive ledger show it.`;
const seed=(opts.target||"").replace(/<[^>]*>/g," ").slice(-300)||"The fog came down before the path did.";
return `\n${seed}\n\n${A} kept walking because stopping would mean deciding, and she was not ready to decide. The pines stood the way they always had — patient, salt-bent, listening. Behind her the steps matched hers for three paces, then stopped, as if the night itself had thought better of following.\n\n"You check the light every hour," ${B} said from the dark, not close, not far. "Even when there's no ship."\n\n"It's not for ships," ${A} said, and hated how true it sounded out loud.\n\nThe lantern at her hip gave one low sputter — not wind, not oil. A color, almost blue, there and gone. Neither of them named it. Some things, in Greyport, you kept by not saying.\n`;}
function rewriteLocal(t){t=String(t||"Sample passage. She walked through the dark woods, afraid.").replace(/<[^>]*>/g," ");return t.split(/(?<=[.!?])\s+/).map(s=>s.replace(/^She walked/i,"She kept walking").replace(/afraid/i,"keeping count of her breaths")).join(" ")+" (Rewritten: same events, fresher rhythm, fewer stock phrases.)";}
function polishLocal(t){t=String(t||"Sample passage.").replace(/<[^>]*>/g," ");let out=t;AIISMS.forEach(p=>{const k=p.split(" ")[0];});out=out.replace(/It wasn't (\w+)\. It was (\w+)\./g,"It was $2, not $1.").replace(/her heart hammered/gi,"her pulse stayed loud").replace(/eyes darkened/gi,"his gaze went still").replace(/air was thick with/gi,"the room held").replace(/couldn't help but/gi,"").replace(/released a breath[^.]*\./gi,"exhaled.");return out+" (Polished: grammar kept, voice kept, repetitions trimmed.)";}
function deAIsm(text){let out=String(text);const hits=[];AIISMS.forEach(p=>{const re=new RegExp(p.replace(/[.*+?^${}()|[\]\\]/g,"\\$&").replace("X","[\\w ]+?").replace("Y","[\\w ]+?"),"gi");const m=out.match(re);if(m)hits.push(...m);});out=out.replace(/It wasn't ([^.]+)\. It was ([^.]+)\./g,"It was $2, not $1.").replace(/Something shifted\./g,"The room went quieter.").replace(/released a breath she didn't know she was holding\./gi,"exhaled.").replace(/The air was thick with/gi,"The room held").replace(/She couldn't help but/gi,"She");return {text:out,hits};}
function continuityCheck(n){const issues=[];const map={};(n.characters||[]).forEach(c=>{if(c.age){if(map[c.name]&&map[c.name]!==c.age)issues.push(`Age changed for ${c.name}: ${map[c.name]} → ${c.age}`);map[c.name]=c.age;}});const dead=(n.memory||[]).filter(m=>/died|dead/i.test(m.text||""));dead.forEach(d=>{const nm=(n.characters||[]).find(c=>(d.text||"").includes(c.name));if(nm)issues.push(`Possible continuity issue: ${nm.name} appears after a death note (“${(d.text||"").slice(0,60)}…”). Verify.`);});allNodes(n).forEach(x=>{if(x.content&&/blue lantern/i.test(x.content)&&n.bible?.canon&&!/blue/i.test(n.bible.canon))issues.push(`Possible continuity issue: “blue lantern” in ${x.title} not recorded in canon.`);});(n.locks||[]).forEach(l=>{allNodes(n).forEach(x=>{if(x.content&&l.text&&x.content.toLowerCase().includes("guardian's name")&&/DO NOT REVEAL/.test(l.kind))issues.push(`Possible continuity issue: locked “${l.text}” may be violated in ${x.title}.`);});});if(!issues.length)issues.push("No contradictions detected in local check. AI deep-check needs an API profile.");return issues;}
