function rLocs(){if(!needNovel())return;const n=cur();$("#view-locations").innerHTML=crudView("Locations",n.locations,["type","appearance","atmosphere","history"],async()=>{await openModal("New location",field("Name","","name")+field("Type","","type")+field("Appearance","","appearance",1),'<button class="btn" id="mOk">Add</button>');const v=collectForm();$("#modal").classList.add("hidden");if(v.name){n.locations.push({id:uid(),...v});save();rLocs();}},async i=>{const c=n.locations[i];await openModal("Edit",field("Name",c.name,"name")+field("Type",c.type,"type")+field("Appearance",c.appearance,"appearance",1)+field("Atmosphere",c.atmosphere,"atmosphere",1)+field("History",c.history,"history",1)+field("Notes",c.notes,"notes",1),'<button class="btn" id="mOk">Save</button>');Object.assign(c,collectForm());$("#modal").classList.add("hidden");save();rLocs();},i=>{n.locations.splice(i,1);save();rLocs();});bindCrud(n.locations);}
