function rLore(){if(!needNovel())return;const n=cur();$("#view-lorebook").innerHTML=crudView("Lorebook",n.lorebook,["category","keys","summary","priority"],async()=>{await openModal("New lore entry",field("Name","","name")+field("Keys / triggers","","keys")+field("Summary","","summary",1)+field("Priority","5","priority"),'<button class="btn" id="mOk">Add</button>');const v=collectForm();$("#modal").classList.add("hidden");n.lorebook.push({id:uid(),always:false,...v});save();rLore();},async i=>{const c=n.lorebook[i];await openModal("Edit",field("Name",c.name,"name")+field("Keys",c.keys,"keys")+field("Summary",c.summary,"summary",1)+field("Priority",c.priority,"priority"),'<button class="btn" id="mOk">Save</button>');Object.assign(c,collectForm());$("#modal").classList.add("hidden");save();rLore();},i=>{n.lorebook.splice(i,1);save();rLore();},`<p class="muted">Smart retrieval: only entries whose keys appear (or Always Active) are sent to AI. Never loads everything.</p>`);bindCrud(n.lorebook);}
