async function genPipeline(k){if(!needNovel())return;const n=cur();$("#gOut").textContent="Pipeline: retrieving canon → characters → summaries → threads → lore → plan…";for(let i=0;i<k;i++){const list=chapterList(n).filter(c=>!words(c.content||""));const target=list[0]||chapterList(n)[0];if(!target)break;try{const r=await aiComplete([{role:"system",content:"Generate Novel Draft pipeline. "+ctxNovel()},{role:"user",content:"Draft chapter: "+target.title+" plan:"+JSON.stringify(n.plans[target.id]||{})}],{mode:"continue",maxTokens:2500});target.content=(target.content||"")+`<p>${esc(r.text).slice(0,4000).replace(/\n\n/g,"</p><p>")}</p>`;target.status="First Draft";n.updated=nowISO();save();}catch(e){$("#gOut").textContent="Error: "+e.message;return;}$("#gOut").textContent=`Drafted ${i+1}/${k}. Continuity updated.`;}renderTop();toast("Draft queue done.");}
