/* ---------- IMPORT / EXPORT / BACKUP ---------- */
function download(name,text,type="text/plain"){const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();}
function exportNovel(n){const txt=`# ${n.title}\n## ${n.subtitle||""}\n\n`+chapters(n).map(c=>`## ${c.title}\n\n${(c.content||"").replace(/<[^>]*>/g,"\n")}\n`).join("\n");download(n.title.replace(/\W+/g,"-")+".md",txt,"text/markdown");S.lastBackup=nowISO();save();toast("Exported + backup stamped.");}
function backupAll(){download("novel-studio-backup-"+new Date().toISOString().slice(0,10)+".json",JSON.stringify(S),"application/json");S.lastBackup=nowISO();save();toast("Entire library backed up.");}
function importLibrary(){const i=document.createElement("input");i.type="file";i.accept=".json";i.onchange=e=>{const f=e.target.files[0];const r=new FileReader();r.onload=()=>{try{const j=JSON.parse(r.result);if(j.novels){S=j;if(!S.profiles)S.profiles=blankStore().profiles;save();render();toast("Library restored.");}}catch{toast("Invalid backup.");}};r.readAsText(f);};i.click();}
function importManuscript(){const i=document.createElement("input");i.type="file";i.accept=".txt,.md";i.onchange=e=>{const f=e.target.files[0];const r=new FileReader();r.onload=()=>{const txt=String(r.result);const parts=txt.split(/^#+\s+|^Chapter\s+\d+/gmi).filter(Boolean);const id=uid();const n={id,title:f.name.replace(/\.\w+$/,""),status:"Drafting",targetWords:80000,created:nowISO(),updated:nowISO(),bible:{},style:{},locks:[],structure:[{id:uid(),type:"part",title:"PART I",children:parts.slice(0,30).map((p,j)=>({id:uid(),type:"chapter",title:"Chapter "+(j+1),status:"First Draft",content:"<p>"+esc(p.slice(0,8000)).replace(/\n\n/g,"</p><p>")+"</p>",children:[]}))}],characters:[],relationships:[],locations:[],world:[],lorebook:[],timeline:[],threads:[],plans:{},versions:[],comments:[],notes:[],bookmarks:[],research:[],refs:[],history:[]};S.novels.push(n);UI.novelId=id;UI.chapterId=n.structure[0].children[0]?.id;save();toast(`Imported ${parts.length} chapters (preview-checked).`);go("write");};r.readAsText(f);};i.click();}
