function palette(q){const items=[];S.novels.forEach(n=>{items.push({t:"Novel: "+n.title,fn:()=>{UI.novelId=n.id;go("write");}});chapters(n).forEach(c=>items.push({t:`${n.title} → ${c.title}`,fn:()=>{UI.novelId=n.id;UI.chapterId=c.id;go("write");}}));(n.characters||[]).forEach(c=>items.push({t:`Character: ${c.name}`,fn:()=>{UI.novelId=n.id;go("characters");}}));});
[["Create Chapter",()=>addChapter()],["Open AI Chat",()=>go("storyroom")],["Focus Mode",()=>enterFocus()],["Continuity Check",()=>{go("write");UI.aiTab="Analyze";renderAITabs();}],["Switch Theme",()=>go("settings")],["Export Novel",()=>novel()&&exportNovel(novel())],["Install App",()=>promptInstall()]].forEach(([t,fn])=>items.push({t:"⌘ "+t,fn}));
const f=q.toLowerCase();return items.filter(i=>i.t.toLowerCase().includes(f)).slice(0,12);}
